SELECT ROW_NUMBER() OVER (ORDER BY QNA_NO DESC) RNUM, QNA_NO, QNA_TITLE, QNA_NAME, TO_CHAR(QNA_DATE, 'YYYY.MM.DD') AS QNA_DATE, QNA_LEVEL, QNA_PASSWD FROM QNA_POSTS
selectQnaDetail
SELECT QNA_NO_SEQ.NEXTVAL FROM DUAL
INSERT INTO QNA_POSTS ( QNA_NO, MEMBER_NO, QNA_NAME, QNA_LEVEL, QNA_CATEGORY, QNA_TITLE, QNA_CONTENT, QNA_DATE, QNA_SECRET, QNA_PASSWD ) VALUES ( #{QNA_NO} , #{MEMBER_NO} , #{QNA_NAME} , 0 , #{QNA_CATEGORY} , #{QNA_TITLE} , #{QNA_CONTENT} , SYSDATE , #{QNA_SECRET} , #{QNA_PASSWD} )
SELECT QNA_NO, QNA_CATEGORY, TO_CHAR(QNA_DATE, 'YYYY.MM.DD') AS QNA_DATE, QNA_TITLE, DBMS_LOB.SUBSTR(QNA_CONTENT, 4000, 1) AS QNA_CONTENT, QNA_NAME, DBMS_LOB.SUBSTR(QNA_AN, 4000, 1) AS QNA_AN FROM QNA_POSTS WHERE QNA_NO = #{QNA_NO}
SELECT QNA_NO, QNA_PASSWD FROM QNA_POSTS WHERE QNA_NO = #{QNA_NO}
UPDATE QNA_POSTS SET QNA_AN = #{QNA_AN}, QNA_LEVEL = 1 WHERE QNA_NO = #{QNA_NO}
DELETE FROM QNA_POSTS WHERE QNA_NO = #{QNA_NO}
SELECT qna_passwd, qna_secret FROM QNA_POSTS WHERE qna_no=#{QNA_NO}
